-- ============================================================
-- นำเข้าคำถามสาขาไฟฟ้า หมวดที่ 10: เครื่องมือวัดไฟฟ้า (Electrical Instrumentation)
-- ไฟล์นี้รันได้อิสระ ไม่ต้องพึ่งไฟล์อื่น (idempotent)
-- ============================================================

begin;

-- ---------- เพิ่มหมวดหมู่ ----------
insert into categories (branch_id, code, name_th, sort_order)
select '448937cf-58c5-4007-b57b-6a8bcf46c2fe', 'instrumentation', 'เครื่องมือวัดไฟฟ้า (Electrical Instrumentation)', 10
where not exists (
  select 1 from categories where branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and code = 'instrumentation'
);

-- ---------- เพิ่มคำถาม (33 ข้อ) ----------
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'มัลติมิเตอร์แบบดิจิทัล (Digital Multimeter) วัดค่าแรงดัน กระแส และความต้านทาน ด้วยหลักการพื้นฐานที่แตกต่างกันอย่างไร', 'การวัดแรงดันทำโดยต่อขนานกับจุดที่ต้องการวัดผ่านความต้านทานภายในสูงมากเพื่อไม่รบกวนวงจร การวัดกระแสทำโดยต่ออนุกรมให้กระแสไหลผ่านความต้านทานภายในต่ำมากแล้ววัดแรงดันตกคร่อม ส่วนการวัดความต้านทานทำโดยจ่ายกระแสอ้างอิงขนาดเล็กเข้าไปในองค์ประกอบที่วัด แล้ววัดแรงดันตกคร่อมเพื่อคำนวณย้อนกลับเป็นค่าความต้านทาน', 'การต่อมัลติมิเตอร์ผิดโหมด เช่น ตั้งโหมดวัดกระแสแต่ไปต่อขนานกับวงจรที่มีแรงดัน อาจทำให้เกิดการลัดวงจรผ่านความต้านทานภายในที่ต่ำมากของมิเตอร์ ซึ่งอาจทำให้มิเตอร์เสียหายหรือเป็นอันตรายได้', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'มัลติมิเตอร์แบบดิจิทัล (Digital Multimeter) วัดค่าแรงดัน กระแส และความต้านทาน ด้วยหลักการพื้นฐานที่แตกต่างกันอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'มิเตอร์แบบ True RMS แตกต่างจากมิเตอร์แบบ Average Responding อย่างไร และเหตุใดจึงมีความสำคัญในการวัดสัญญาณที่มีฮาร์มอนิก', 'มิเตอร์แบบ True RMS คำนวณค่า RMS ที่แท้จริงของรูปคลื่นไม่ว่าจะมีรูปร่างเบี่ยงเบนจากไซน์บริสุทธิ์เพียงใด ในขณะที่มิเตอร์แบบ Average Responding วัดค่าเฉลี่ยของรูปคลื่นแล้วคูณด้วยตัวคูณคงที่ที่คำนวณมาสำหรับรูปคลื่นไซน์บริสุทธิ์เท่านั้น ทำให้อ่านค่าคลาดเคลื่อนเมื่อวัดสัญญาณที่มีฮาร์มอนิกสูง', 'ในระบบไฟฟ้าปัจจุบันที่มีอุปกรณ์อิเล็กทรอนิกส์กำลังจำนวนมากก่อให้เกิดฮาร์มอนิก การใช้มิเตอร์แบบ True RMS จึงมีความจำเป็นเพื่อให้ได้ค่าการวัดที่ถูกต้องแม่นยำ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'มิเตอร์แบบ True RMS แตกต่างจากมิเตอร์แบบ Average Responding อย่างไร และเหตุใดจึงมีความสำคัญในการวัดสัญญาณที่มีฮาร์มอนิก'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ออสซิลโลสโคป (Oscilloscope) มีประโยชน์ในการวินิจฉัยปัญหาทางไฟฟ้าที่มัลติมิเตอร์ทั่วไปไม่สามารถทำได้อย่างไร', 'ออสซิลโลสโคปแสดงรูปคลื่นของสัญญาณไฟฟ้าตามเวลาจริง ทำให้สามารถมองเห็นลักษณะรูปคลื่น ความผิดเพี้ยน สัญญาณรบกวนชั่วครู่ (Transient) และความสัมพันธ์เชิงเวลาระหว่างสัญญาณหลายจุด ซึ่งมัลติมิเตอร์ที่แสดงเพียงค่าตัวเลขเดียวไม่สามารถแสดงข้อมูลเหล่านี้ได้', 'ออสซิลโลสโคปจึงเป็นเครื่องมือสำคัญในการวินิจฉัยปัญหาที่เกี่ยวข้องกับสัญญาณผิดเพี้ยน การสวิตชิ่งผิดปกติ หรือสัญญาณรบกวนที่เกิดขึ้นเพียงชั่วครู่ ซึ่งเป็นปัญหาที่พบบ่อยในวงจรอิเล็กทรอนิกส์กำลังและระบบควบคุม', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ออสซิลโลสโคป (Oscilloscope) มีประโยชน์ในการวินิจฉัยปัญหาทางไฟฟ้าที่มัลติมิเตอร์ทั่วไปไม่สามารถทำได้อย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'แคลมป์มิเตอร์ (Clamp Meter) วัดกระแสไฟฟ้าโดยไม่ต้องตัดสายไฟหรือสัมผัสตัวนำโดยตรงได้อย่างไร', 'อาศัยหลักการเหนี่ยวนำแม่เหล็กไฟฟ้า โดยขากรรไกรของแคลมป์มิเตอร์คล้องรอบสายไฟที่ต้องการวัด สนามแม่เหล็กที่เกิดจากกระแสไฟฟ้าที่ไหลผ่านสายจะเหนี่ยวนำให้เกิดสัญญาณในขดลวดภายในแคลมป์ ซึ่งนำมาแปลงและคำนวณย้อนกลับเป็นค่ากระแสที่ไหลในสายนั้น', 'วิธีนี้สะดวกและปลอดภัยกว่าการวัดกระแสด้วยมัลติมิเตอร์แบบต่ออนุกรมที่ต้องตัดวงจรเพื่อสอดมิเตอร์เข้าไป จึงนิยมใช้อย่างแพร่หลายในการวัดกระแสภาคสนามโดยไม่ต้องหยุดการทำงานของวงจร', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'แคลมป์มิเตอร์ (Clamp Meter) วัดกระแสไฟฟ้าโดยไม่ต้องตัดสายไฟหรือสัมผัสตัวนำโดยตรงได้อย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดแคลมป์มิเตอร์แบบธรรมดาจึงไม่สามารถวัดกระแสไฟฟ้ากระแสตรงได้ และต้องใช้เทคโนโลยีใดเพิ่มเติมเพื่อวัดกระแสตรงได้', 'เพราะหลักการเหนี่ยวนำแม่เหล็กไฟฟ้าอาศัยการเปลี่ยนแปลงของสนามแม่เหล็กตามเวลา ซึ่งเกิดขึ้นเฉพาะกับกระแสสลับที่มีการเปลี่ยนแปลงขนาดและทิศทางตลอดเวลา กระแสตรงที่มีขนาดคงที่จึงไม่สร้างการเปลี่ยนแปลงของสนามแม่เหล็กที่จะเหนี่ยวนำสัญญาณได้ แคลมป์มิเตอร์สำหรับวัดกระแสตรงจึงต้องใช้เทคโนโลยีเซนเซอร์ฮอลล์เอฟเฟกต์ (Hall Effect Sensor) แทน', 'เซนเซอร์ฮอลล์เอฟเฟกต์สามารถตรวจจับความเข้มของสนามแม่เหล็กได้โดยตรงแม้ในสภาวะคงที่ ทำให้สามารถวัดกระแสตรงได้ ต่างจากหลักการเหนี่ยวนำแม่เหล็กไฟฟ้าที่ใช้ได้เฉพาะกับกระแสสลับเท่านั้น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดแคลมป์มิเตอร์แบบธรรมดาจึงไม่สามารถวัดกระแสไฟฟ้ากระแสตรงได้ และต้องใช้เทคโนโลยีใดเพิ่มเติมเพื่อวัดกระแสตรงได้'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'วัตต์มิเตอร์ (Wattmeter) วัดกำลังไฟฟ้าจริงในวงจร AC ด้วยหลักการอย่างไร', 'วัตต์มิเตอร์มีขดลวดสองชุด คือขดลวดกระแส (Current Coil) ที่ต่ออนุกรมกับวงจรเพื่อวัดกระแส และขดลวดแรงดัน (Potential Coil) ที่ต่อขนานกับวงจรเพื่อวัดแรงดัน แรงบิดที่เกิดขึ้นบนเข็มชี้หรือสัญญาณเอาต์พุตจะแปรผันตามผลคูณของกระแสและแรงดันคูณด้วยโคไซน์ของมุมเฟสระหว่างทั้งสอง ซึ่งตรงกับสูตรการคำนวณกำลังไฟฟ้าจริง', 'การต่อวัตต์มิเตอร์อย่างถูกวิธีต้องคำนึงถึงทั้งการต่อขดลวดกระแสแบบอนุกรมและขดลวดแรงดันแบบขนานให้ถูกต้องพร้อมกัน ต่างจากแอมมิเตอร์หรือโวลต์มิเตอร์ที่ต่อเพียงแบบเดียว', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'วัตต์มิเตอร์ (Wattmeter) วัดกำลังไฟฟ้าจริงในวงจร AC ด้วยหลักการอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เครื่องวัดคุณภาพไฟฟ้า (Power Quality Analyzer) สามารถตรวจวัดพารามิเตอร์ใดบ้างที่มัลติมิเตอร์ทั่วไปไม่สามารถวัดได้', 'สามารถตรวจวัดพารามิเตอร์เชิงคุณภาพของไฟฟ้า เช่น ปริมาณฮาร์มอนิกแต่ละลำดับ (Total Harmonic Distortion), แรงดันตกชั่วครู่ (Voltage Sag/Dip), แรงดันเกินชั่วครู่ (Voltage Swell), ความไม่สมดุลระหว่างเฟส (Voltage/Current Unbalance) และเหตุการณ์ไฟดับสั้นๆ (Interruption)', 'เครื่องมือนี้มีประโยชน์อย่างมากในการวินิจฉัยปัญหาที่เกิดจากคุณภาพไฟฟ้าไม่ดี เช่น อุปกรณ์อิเล็กทรอนิกส์ทำงานผิดปกติโดยไม่ทราบสาเหตุ ซึ่งมัลติมิเตอร์ทั่วไปที่วัดเพียงค่า RMS พื้นฐานไม่สามารถวินิจฉัยได้', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เครื่องวัดคุณภาพไฟฟ้า (Power Quality Analyzer) สามารถตรวจวัดพารามิเตอร์ใดบ้างที่มัลติมิเตอร์ทั่วไปไม่สามารถวัดได้'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เครื่องวัดค่าความต้านทานดิน (Earth Resistance Tester) ใช้หลักการวัดแบบใดที่นิยมใช้กันมากที่สุด', 'หลักการที่นิยมใช้มากที่สุดคือวิธี Fall of Potential (หรือ 3-Point Method) โดยปักหลักดินเสริม 2 จุดที่ระยะห่างต่างๆ จากจุดที่ต้องการวัด แล้ววัดความต้านทานระหว่างจุดที่ต้องการวัดกับหลักดินเสริมเหล่านั้น เพื่อคำนวณค่าความต้านทานดินที่แท้จริง', 'การวัดที่แม่นยำต้องเลือกระยะห่างของหลักดินเสริมให้เหมาะสม โดยทั่วไปแนะนำให้หลักดินเสริมตัวไกลอยู่ห่างจากจุดที่วัดอย่างน้อยประมาณ 5-10 เท่าของความลึกหรือความยาวของระบบสายดินที่ทดสอบ เพื่อให้ผลการวัดไม่ได้รับผลกระทบจากพื้นที่อิทธิพลของระบบสายดินที่ทดสอบ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เครื่องวัดค่าความต้านทานดิน (Earth Resistance Tester) ใช้หลักการวัดแบบใดที่นิยมใช้กันมากที่สุด'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'มิเตอร์วัดพลังงานไฟฟ้าแบบดิจิทัล (Digital Energy Meter) มีข้อได้เปรียบเหนือมิเตอร์แบบจานหมุน (Induction Disk Meter) แบบดั้งเดิมอย่างไร', 'มิเตอร์แบบดิจิทัลมีความแม่นยำสูงกว่า สามารถวัดและบันทึกข้อมูลได้ละเอียดขึ้น เช่น ค่าพลังงานแยกตามช่วงเวลา (Time of Use) ตัวประกอบกำลัง และสามารถส่งข้อมูลผ่านระบบสื่อสารทางไกลได้ (Smart Meter) ต่างจากมิเตอร์แบบจานหมุนที่วัดได้เพียงค่าพลังงานสะสมรวมและต้องอ่านค่าด้วยมนุษย์', 'มิเตอร์อัจฉริยะ (Smart Meter) ที่ใช้เทคโนโลยีดิจิทัลกำลังเข้ามาแทนที่มิเตอร์แบบจานหมุนอย่างต่อเนื่อง เนื่องจากช่วยให้การไฟฟ้าสามารถบริหารจัดการระบบและเก็บข้อมูลการใช้ไฟฟ้าได้อย่างมีประสิทธิภาพมากขึ้น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'มิเตอร์วัดพลังงานไฟฟ้าแบบดิจิทัล (Digital Energy Meter) มีข้อได้เปรียบเหนือมิเตอร์แบบจานหมุน (Induction Disk Meter) แบบดั้งเดิมอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เครื่องวัดลำดับเฟส (Phase Sequence Meter) มีประโยชน์อย่างไรในการติดตั้งอุปกรณ์ไฟฟ้า 3 เฟส', 'ใช้ตรวจสอบลำดับเฟส (Phase Sequence) ของแหล่งจ่ายไฟฟ้า 3 เฟสว่าเป็นไปตามลำดับที่ถูกต้องหรือไม่ ก่อนเชื่อมต่ออุปกรณ์ที่ไวต่อทิศทางการหมุน เช่น มอเตอร์ 3 เฟส เพื่อป้องกันการหมุนผิดทิศทางซึ่งอาจก่อให้เกิดความเสียหายต่อเครื่องจักรที่ขับเคลื่อนอยู่', 'การตรวจสอบลำดับเฟสมีความสำคัญเป็นพิเศษเมื่อเชื่อมต่อแหล่งจ่ายไฟฟ้าใหม่หรือเปลี่ยนแปลงการต่อสาย เพื่อยืนยันว่าลำดับเฟสถูกต้องก่อนที่จะสตาร์ทมอเตอร์หรืออุปกรณ์ที่ขับเคลื่อนภาระที่มีทิศทางเฉพาะ เช่น สายพานลำเลียง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เครื่องวัดลำดับเฟส (Phase Sequence Meter) มีประโยชน์อย่างไรในการติดตั้งอุปกรณ์ไฟฟ้า 3 เฟส'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เครื่องวิเคราะห์แบตเตอรี่ (Battery Analyzer) ใช้ตรวจสอบสภาพของแบตเตอรี่ด้วยพารามิเตอร์ใดบ้าง', 'ตรวจสอบพารามิเตอร์ เช่น แรงดันไฟฟ้าของแต่ละเซลล์ ความต้านทานภายใน (Internal Resistance) ความจุที่แท้จริง (Actual Capacity) เทียบกับความจุพิกัด และความสามารถในการรับและจ่ายกระแสภายใต้ภาระ', 'ความต้านทานภายในที่เพิ่มขึ้นมักเป็นสัญญาณบ่งชี้ถึงการเสื่อมสภาพของแบตเตอรี่ตามอายุการใช้งาน การตรวจสอบเป็นระยะช่วยให้สามารถวางแผนเปลี่ยนแบตเตอรี่ก่อนที่จะเกิดความล้มเหลวในระบบสำรองไฟฟ้าที่สำคัญ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เครื่องวิเคราะห์แบตเตอรี่ (Battery Analyzer) ใช้ตรวจสอบสภาพของแบตเตอรี่ด้วยพารามิเตอร์ใดบ้าง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การสอบเทียบ (Calibration) เครื่องมือวัดไฟฟ้ามีความสำคัญอย่างไร และควรทำเมื่อใด', 'การสอบเทียบคือกระบวนการเปรียบเทียบค่าที่เครื่องมือวัดอ่านได้กับค่ามาตรฐานอ้างอิงที่มีความแม่นยำสูงกว่า เพื่อตรวจสอบและปรับแก้ความคลาดเคลื่อนของเครื่องมือ ควรทำเป็นระยะตามรอบเวลาที่กำหนด หรือเมื่อเครื่องมือได้รับการกระแทกรุนแรง หรือเมื่อผลการวัดเริ่มมีความน่าสงสัย', 'เครื่องมือวัดที่ไม่ได้สอบเทียบเป็นระยะอาจให้ค่าที่คลาดเคลื่อนโดยที่ผู้ใช้งานไม่ทราบ ซึ่งอาจนำไปสู่การตัดสินใจที่ผิดพลาดในการวินิจฉัยปัญหาหรือควบคุมคุณภาพ โดยเฉพาะในงานที่ต้องการความแม่นยำสูง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การสอบเทียบ (Calibration) เครื่องมือวัดไฟฟ้ามีความสำคัญอย่างไร และควรทำเมื่อใด'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ความคลาดเคลื่อนเชิงระบบ (Systematic Error) และความคลาดเคลื่อนแบบสุ่ม (Random Error) ของการวัดแตกต่างกันอย่างไร', 'ความคลาดเคลื่อนเชิงระบบเกิดขึ้นอย่างสม่ำเสมอในทิศทางเดียวทุกครั้งที่วัด เช่น จากการสอบเทียบที่ไม่ถูกต้อง สามารถแก้ไขได้ด้วยการสอบเทียบใหม่ ส่วนความคลาดเคลื่อนแบบสุ่มเกิดขึ้นแบบไม่แน่นอนทั้งขนาดและทิศทางในแต่ละครั้งที่วัด ซึ่งไม่สามารถกำจัดได้ทั้งหมดแต่สามารถลดผลกระทบได้ด้วยการวัดซ้ำหลายครั้งแล้วหาค่าเฉลี่ย', 'การเข้าใจความแตกต่างของความคลาดเคลื่อนทั้งสองประเภทช่วยให้วิศวกรสามารถเลือกวิธีจัดการที่เหมาะสม เช่น การสอบเทียบเพื่อแก้ความคลาดเคลื่อนเชิงระบบ หรือการวัดซ้ำหลายครั้งเพื่อลดผลกระทบของความคลาดเคลื่อนแบบสุ่ม', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ความคลาดเคลื่อนเชิงระบบ (Systematic Error) และความคลาดเคลื่อนแบบสุ่ม (Random Error) ของการวัดแตกต่างกันอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการต่อโวลต์มิเตอร์ที่มีความต้านทานภายในต่ำเกินไปเข้ากับวงจรที่มีความต้านทานสูง อาจทำให้ค่าที่วัดได้คลาดเคลื่อนไปจากค่าจริง', 'เมื่อโวลต์มิเตอร์มีความต้านทานภายในต่ำเกินไปเมื่อเทียบกับความต้านทานของวงจรที่วัด การต่อโวลต์มิเตอร์เข้าไปจะดึงกระแสจากวงจรมากพอที่จะเปลี่ยนแปลงสภาวะการทำงานเดิมของวงจร (Loading Effect) ทำให้ค่าแรงดันที่วัดได้ต่ำกว่าค่าจริงที่ควรเป็นก่อนต่อมิเตอร์เข้าไป', 'ปรากฏการณ์นี้เป็นตัวอย่างของหลักการที่ว่าเครื่องมือวัดในทางปฏิบัติไม่ใช่อุปกรณ์ในอุดมคติ การเลือกเครื่องมือวัดที่มีความต้านทานภายในสูงเพียงพอ (สำหรับโวลต์มิเตอร์) จึงมีความสำคัญเมื่อวัดวงจรที่มีความต้านทานสูง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการต่อโวลต์มิเตอร์ที่มีความต้านทานภายในต่ำเกินไปเข้ากับวงจรที่มีความต้านทานสูง อาจทำให้ค่าที่วัดได้คลาดเคลื่อนไปจากค่าจริง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เครื่องมือวัดที่มีคลาสความแม่นยำ (Accuracy Class) 0.5 และคลาส 1.0 มีความหมายแตกต่างกันอย่างไร', 'ตัวเลขคลาสความแม่นยำบ่งบอกถึงค่าความคลาดเคลื่อนสูงสุดที่ยอมรับได้ คิดเป็นเปอร์เซ็นต์ของค่าเต็มสเกล (Full Scale) เครื่องมือคลาส 0.5 มีความคลาดเคลื่อนสูงสุดไม่เกิน 0.5% ของค่าเต็มสเกล ซึ่งมีความแม่นยำสูงกว่าเครื่องมือคลาส 1.0 ที่มีความคลาดเคลื่อนสูงสุดไม่เกิน 1.0%', 'การเลือกคลาสความแม่นยำของเครื่องมือวัดต้องเหมาะสมกับวัตถุประสงค์การใช้งาน เช่น เครื่องมือที่ใช้เพื่อการซื้อขายพลังงานไฟฟ้า (Revenue Metering) มักต้องการคลาสความแม่นยำสูงกว่าเครื่องมือที่ใช้เพื่อการตรวจสอบทั่วไปเท่านั้น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เครื่องมือวัดที่มีคลาสความแม่นยำ (Accuracy Class) 0.5 และคลาส 1.0 มีความหมายแตกต่างกันอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เครื่องมือวัดฉนวนแบบ Time Resistance Method หรือ Polarization Index (PI) ใช้ประเมินสภาพฉนวนแตกต่างจากการวัดค่าความต้านทานฉนวนแบบจุดเดียวอย่างไร', 'วิธีนี้วัดค่าความต้านทานฉนวนที่เวลาต่างกันสองจุด (เช่น ที่ 1 นาทีและ 10 นาที) แล้วคำนวณอัตราส่วนระหว่างสองค่านั้น ฉนวนที่มีสภาพดีมักแสดงค่าความต้านทานที่เพิ่มขึ้นตามเวลาเนื่องจากกระบวนการโพลาไรเซชันของโมเลกุลในฉนวน ในขณะที่ฉนวนที่มีความชื้นหรือปนเปื้อนมักแสดงอัตราส่วนที่ต่ำใกล้เคียงหนึ่ง', 'วิธีนี้ให้ข้อมูลเชิงลึกเกี่ยวกับสภาพฉนวนมากกว่าการวัดค่าความต้านทานที่จุดเดียว เนื่องจากลดผลกระทบจากปัจจัยแวดล้อม เช่น อุณหภูมิ ซึ่งอาจทำให้การเปรียบเทียบค่าความต้านทานจุดเดียวระหว่างครั้งต่างกันคลาดเคลื่อนได้', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เครื่องมือวัดฉนวนแบบ Time Resistance Method หรือ Polarization Index (PI) ใช้ประเมินสภาพฉนวนแตกต่างจากการวัดค่าความต้านทานฉนวนแบบจุดเดียวอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การใช้เครื่องมือวัดกล้องถ่ายภาพความร้อน (Thermal Imaging Camera) ในการตรวจสอบระบบไฟฟ้ามีประโยชน์อย่างไร', 'สามารถตรวจจับจุดที่มีอุณหภูมิสูงผิดปกติในอุปกรณ์ไฟฟ้า เช่น จุดต่อหลวมที่มีความต้านทานสูงกว่าปกติ หรือโหลดไม่สมดุลระหว่างเฟส ซึ่งจุดเหล่านี้มักมีความร้อนสูงกว่าบริเวณโดยรอบก่อนที่จะพัฒนาเป็นความเสียหายรุนแรงหรือเพลิงไหม้', 'การตรวจสอบด้วยกล้องถ่ายภาพความร้อนเป็นเทคนิคการบำรุงรักษาเชิงป้องกันแบบไม่ต้องสัมผัสหรือหยุดการทำงานของระบบ (Non-contact, Non-intrusive) ที่ได้รับความนิยมมากขึ้นในการตรวจสอบสภาพระบบไฟฟ้าอย่างสม่ำเสมอ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การใช้เครื่องมือวัดกล้องถ่ายภาพความร้อน (Thermal Imaging Camera) ในการตรวจสอบระบบไฟฟ้ามีประโยชน์อย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การวัดค่ากำลังไฟฟ้าในวงจร 3 เฟสแบบสมดุล สามารถใช้วัตต์มิเตอร์เพียงตัวเดียวได้หรือไม่ และมีเงื่อนไขอย่างไร', 'สามารถทำได้หากระบบมีความสมดุลอย่างสมบูรณ์ทั้งสามเฟส โดยวัดกำลังไฟฟ้าเพียงเฟสเดียวแล้วคูณด้วยสาม ก็จะได้กำลังไฟฟ้ารวมของทั้งระบบ แต่วิธีนี้ใช้ไม่ได้หากระบบมีความไม่สมดุลระหว่างเฟส ซึ่งในกรณีนั้นจำเป็นต้องวัดด้วยวิธีที่ครอบคลุมทุกเฟส เช่น Two-Wattmeter Method หรือ Three-Wattmeter Method', 'ในทางปฏิบัติ ระบบไฟฟ้ากำลังจริงมักมีความไม่สมดุลอยู่บ้างเสมอ การวัดด้วยวิธีที่ครอบคลุมทุกเฟสจึงให้ผลลัพธ์ที่แม่นยำกว่าและเป็นที่นิยมใช้มากกว่าการวัดเพียงเฟสเดียว', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การวัดค่ากำลังไฟฟ้าในวงจร 3 เฟสแบบสมดุล สามารถใช้วัตต์มิเตอร์เพียงตัวเดียวได้หรือไม่ และมีเงื่อนไขอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการวัดค่าความต้านทานของขดลวดมอเตอร์หรือหม้อแปลงด้วยโอห์มมิเตอร์ทั่วไป จึงอาจให้ผลลัพธ์ที่ไม่แม่นยำเพียงพอสำหรับการวินิจฉัยความผิดปกติเล็กน้อย', 'เพราะค่าความต้านทานของขดลวดขนาดใหญ่มักมีค่าต่ำมาก (ระดับมิลลิโอห์มถึงโอห์มเดียว) ซึ่งใกล้เคียงกับความต้านทานของสายวัดและจุดสัมผัสของโอห์มมิเตอร์ทั่วไป ทำให้ความคลาดเคลื่อนจากส่วนเหล่านี้มีนัยสำคัญเทียบกับค่าที่ต้องการวัด', 'การวัดค่าความต้านทานต่ำที่แม่นยำจึงมักต้องใช้เทคนิคการวัดแบบ 4-Wire (Kelvin Bridge หรือ Micro-ohmmeter) ที่แยกเส้นทางการจ่ายกระแสและเส้นทางการวัดแรงดันออกจากกัน เพื่อขจัดผลกระทบจากความต้านทานของสายวัดและจุดสัมผัส', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการวัดค่าความต้านทานของขดลวดมอเตอร์หรือหม้อแปลงด้วยโอห์มมิเตอร์ทั่วไป จึงอาจให้ผลลัพธ์ที่ไม่แม่นยำเพียงพอสำหรับการวินิจฉัยความผิดปกติเล็กน้อย'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เครื่องบันทึกข้อมูล (Data Logger) มีบทบาทอย่างไรในการติดตามพารามิเตอร์ทางไฟฟ้าในระยะยาว', 'ทำหน้าที่บันทึกค่าที่วัดได้อย่างต่อเนื่องตามช่วงเวลาที่กำหนด เก็บไว้เป็นข้อมูลย้อนหลังสำหรับการวิเคราะห์แนวโน้ม การวินิจฉัยปัญหาที่เกิดขึ้นเป็นระยะๆ ที่ยากต่อการตรวจจับด้วยการวัดแบบจุดเดียว หรือการติดตามการใช้พลังงานในช่วงเวลาต่างๆ', 'ตัวอย่างการใช้งาน เช่น การบันทึกโหลดของหม้อแปลงตลอด 24 ชั่วโมงเพื่อวิเคราะห์ Load Factor หรือการบันทึกเหตุการณ์แรงดันตกที่เกิดขึ้นไม่บ่อยแต่ส่งผลกระทบต่อกระบวนการผลิตในโรงงาน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เครื่องบันทึกข้อมูล (Data Logger) มีบทบาทอย่างไรในการติดตามพารามิเตอร์ทางไฟฟ้าในระยะยาว'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการวัดกระแสไฟฟ้าด้วยแอมมิเตอร์แบบต่ออนุกรมจึงต้องเลือกแอมมิเตอร์ที่มีความต้านทานภายในต่ำมาก ต่างจากโวลต์มิเตอร์ที่ต้องการความต้านทานภายในสูง', 'เพราะแอมมิเตอร์ต่ออนุกรมกับวงจร หากมีความต้านทานภายในสูง จะเพิ่มความต้านทานรวมของวงจรและลดกระแสที่ไหลจริงลงจากค่าเดิมก่อนต่อมิเตอร์ ทำให้ค่าที่วัดได้ต่ำกว่าค่าจริง ในขณะที่โวลต์มิเตอร์ต่อขนาน จำเป็นต้องมีความต้านทานสูงเพื่อไม่ให้ดึงกระแสออกจากวงจรมากเกินไป', 'หลักการเลือกความต้านทานภายในของเครื่องมือวัดที่ต่างกันตามลักษณะการต่อวงจรนี้ เป็นแนวคิดพื้นฐานสำคัญที่ช่วยให้เข้าใจว่าเหตุใดเครื่องมือวัดแต่ละประเภทจึงถูกออกแบบให้มีคุณสมบัติทางไฟฟ้าที่แตกต่างกัน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการวัดกระแสไฟฟ้าด้วยแอมมิเตอร์แบบต่ออนุกรมจึงต้องเลือกแอมมิเตอร์ที่มีความต้านทานภายในต่ำมาก ต่างจากโวลต์มิเตอร์ที่ต้องการความต้านทานภายในสูง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เครื่องวิเคราะห์สเปกตรัมความถี่ (Frequency Spectrum Analyzer) ใช้ในการวินิจฉัยปัญหาทางไฟฟ้าลักษณะใด', 'ใช้แยกแยะและแสดงองค์ประกอบความถี่ต่างๆ ที่ประกอบกันเป็นสัญญาณเชิงซ้อน ทำให้สามารถระบุได้ว่าความถี่ใดมีความเข้มสูงผิดปกติ เช่น การระบุลำดับฮาร์มอนิกที่เป็นปัญหาหลักในระบบไฟฟ้า หรือการตรวจจับความถี่การสั่นสะเทือนทางกลที่ผิดปกติในมอเตอร์ผ่านการวิเคราะห์กระแสไฟฟ้า', 'การวิเคราะห์สเปกตรัมความถี่ของกระแสมอเตอร์ (Motor Current Signature Analysis) เป็นเทคนิคที่ได้รับความนิยมเพิ่มขึ้นในการวินิจฉัยปัญหาทางกลของมอเตอร์ เช่น ตลับลูกปืนเสียหายหรือแกนเพลาไม่ตรงศูนย์ โดยไม่ต้องหยุดเครื่องหรือติดตั้งเซนเซอร์ทางกลเพิ่มเติม', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เครื่องวิเคราะห์สเปกตรัมความถี่ (Frequency Spectrum Analyzer) ใช้ในการวินิจฉัยปัญหาทางไฟฟ้าลักษณะใด'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดในการวัดค่าทางไฟฟ้าในสภาพแวดล้อมที่มีสัญญาณรบกวนทางแม่เหล็กไฟฟ้าสูง จึงควรใช้สายวัดแบบมีชีลด์ (Shielded Cable)', 'สายวัดแบบมีชีลด์มีตัวนำโลหะห่อหุ้มรอบสายสัญญาณหลัก ทำหน้าที่ดักจับสัญญาณรบกวนทางแม่เหล็กไฟฟ้าจากภายนอกก่อนที่จะรบกวนสัญญาณที่ต้องการวัด ช่วยรักษาความถูกต้องของสัญญาณที่ส่งไปยังเครื่องมือวัด โดยเฉพาะเมื่อสัญญาณที่วัดมีขนาดเล็กและระยะทางเดินสายไกล', 'การต่อกราวด์ชีลด์อย่างถูกวิธี (มักต่อกราวด์ที่ปลายด้านเดียวเพื่อป้องกัน Ground Loop) เป็นข้อพิจารณาสำคัญเพิ่มเติมในการใช้สายวัดแบบมีชีลด์ให้ได้ประสิทธิภาพในการป้องกันสัญญาณรบกวนอย่างเต็มที่', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดในการวัดค่าทางไฟฟ้าในสภาพแวดล้อมที่มีสัญญาณรบกวนทางแม่เหล็กไฟฟ้าสูง จึงควรใช้สายวัดแบบมีชีลด์ (Shielded Cable)'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การวัดค่าตัวประกอบกำลัง (Power Factor) ด้วยมิเตอร์แบบ Power Factor Meter โดยตรง มีหลักการวัดอย่างไร', 'มิเตอร์ชนิดนี้วัดมุมเฟสระหว่างกระแสและแรงดันในวงจรโดยตรง แล้วคำนวณค่าโคไซน์ของมุมเฟสนั้นเพื่อแสดงเป็นค่าตัวประกอบกำลัง โดยอาศัยการเปรียบเทียบจังหวะเวลาที่สัญญาณทั้งสองผ่านจุดศูนย์ (Zero Crossing) ในแต่ละไซเคิล', 'มิเตอร์บางรุ่นยังสามารถระบุได้ว่าตัวประกอบกำลังเป็นแบบ Lagging (กระแสล้าหลังแรงดัน จากโหลดเหนี่ยวนำ) หรือ Leading (กระแสนำหน้าแรงดัน จากโหลดตัวเก็บประจุ) ซึ่งเป็นข้อมูลสำคัญในการวางแผนติดตั้งอุปกรณ์ชดเชยตัวประกอบกำลัง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การวัดค่าตัวประกอบกำลัง (Power Factor) ด้วยมิเตอร์แบบ Power Factor Meter โดยตรง มีหลักการวัดอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการวัดค่ากระแสรั่วไหล (Leakage Current) ในอุปกรณ์ไฟฟ้าจึงต้องใช้เครื่องมือวัดที่มีความไวสูงเป็นพิเศษ', 'เพราะกระแสรั่วไหลที่เป็นอันตรายต่อชีวิตมนุษย์มักมีขนาดเพียงไม่กี่มิลลิแอมป์เท่านั้น ซึ่งเล็กมากเมื่อเทียบกับกระแสโหลดปกติที่อาจสูงถึงหลายสิบหรือหลายร้อยแอมป์ เครื่องมือวัดทั่วไปที่ออกแบบมาสำหรับวัดกระแสโหลดขนาดใหญ่จึงไม่มีความละเอียดเพียงพอที่จะตรวจจับกระแสรั่วไหลขนาดเล็กนี้ได้', 'การวัดกระแสรั่วไหลมักใช้แคลมป์มิเตอร์ชนิดพิเศษที่คล้องรอบสายไฟทั้งเส้นวงจร (ทั้งสายไลน์และสายนิวทรัล) พร้อมกัน โดยวัดค่าผลต่างของกระแสที่ไหลเข้าและออก ซึ่งในสภาวะปกติควรมีค่าใกล้ศูนย์ หากมีค่าแตกต่างอย่างมีนัยสำคัญ แสดงว่ามีกระแสไหลรั่วออกนอกวงจรไปที่อื่น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการวัดค่ากระแสรั่วไหล (Leakage Current) ในอุปกรณ์ไฟฟ้าจึงต้องใช้เครื่องมือวัดที่มีความไวสูงเป็นพิเศษ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การทดสอบแบบ Hipot Test (High Potential Test) แตกต่างจากการวัดความต้านทานฉนวนทั่วไปอย่างไร', 'Hipot Test จ่ายแรงดันสูงกว่าแรงดันใช้งานปกติมากในระยะเวลาสั้นๆ เพื่อยืนยันว่าฉนวนสามารถทนแรงดันเกินได้โดยไม่เกิดการวาบไฟหรือพังทลาย ต่างจากการวัดความต้านทานฉนวนทั่วไปที่ใช้แรงดันทดสอบต่ำกว่าและมุ่งประเมินค่าความต้านทานเชิงปริมาณของฉนวน มากกว่าทดสอบความสามารถทนแรงดันจริง', 'Hipot Test มักใช้เป็นการทดสอบขั้นสุดท้ายหลังการผลิตหรือซ่อมบำรุงอุปกรณ์ไฟฟ้า เพื่อยืนยันว่าฉนวนมีความสมบูรณ์เพียงพอสำหรับใช้งานจริง แต่ต้องระมัดระวังเนื่องจากการทดสอบนี้มีความเสี่ยงที่จะทำให้ฉนวนที่มีจุดอ่อนอยู่แล้ววิบัติระหว่างการทดสอบได้', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การทดสอบแบบ Hipot Test (High Potential Test) แตกต่างจากการวัดความต้านทานฉนวนทั่วไปอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เครื่องวัดสนามแม่เหล็กไฟฟ้า (EMF Meter) ใช้ตรวจวัดพารามิเตอร์ใด และมีความสำคัญในบริบทใด', 'ใช้ตรวจวัดความเข้มของสนามแม่เหล็กไฟฟ้าที่แผ่ออกจากอุปกรณ์ไฟฟ้าหรือสายส่งไฟฟ้าแรงสูง มีความสำคัญในการประเมินความสอดคล้องกับมาตรฐานความปลอดภัยด้านสิ่งแวดล้อมและสุขภาพ โดยเฉพาะในพื้นที่ที่มีการอยู่อาศัยใกล้กับสายส่งไฟฟ้าแรงสูงหรือสถานีไฟฟ้า', 'การตรวจวัดนี้มักเป็นส่วนหนึ่งของการประเมินผลกระทบสิ่งแวดล้อม (EIA) สำหรับโครงการก่อสร้างสายส่งหรือสถานีไฟฟ้าใหม่ในพื้นที่ที่มีชุมชนอาศัยอยู่ใกล้เคียง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เครื่องวัดสนามแม่เหล็กไฟฟ้า (EMF Meter) ใช้ตรวจวัดพารามิเตอร์ใด และมีความสำคัญในบริบทใด'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดในการตรวจวัดคุณภาพไฟฟ้าในระยะยาว จึงควรพิจารณาช่วงเวลาและสภาวะการทำงานของโรงงานที่หลากหลาย ไม่ใช่วัดเพียงช่วงเวลาสั้นๆ ครั้งเดียว', 'เพราะปัญหาคุณภาพไฟฟ้าหลายประเภท เช่น ฮาร์มอนิกหรือความไม่สมดุล อาจเกิดขึ้นเฉพาะในบางช่วงเวลาที่มีการทำงานของเครื่องจักรบางประเภท หรือในบางสภาวะโหลดที่แตกต่างจากปกติ การวัดเพียงช่วงเวลาสั้นๆ อาจไม่สามารถจับปัญหาที่แท้จริงได้ครบถ้วน', 'การตรวจวัดคุณภาพไฟฟ้าที่ดีจึงมักดำเนินการต่อเนื่องอย่างน้อยหนึ่งสัปดาห์เต็ม เพื่อครอบคลุมรูปแบบการทำงานที่แตกต่างกันทั้งวันทำการและวันหยุด รวมถึงช่วงเวลาที่มีการสตาร์ทเครื่องจักรขนาดใหญ่', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดในการตรวจวัดคุณภาพไฟฟ้าในระยะยาว จึงควรพิจารณาช่วงเวลาและสภาวะการทำงานของโรงงานที่หลากหลาย ไม่ใช่วัดเพียงช่วงเวลาสั้นๆ ครั้งเดียว'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดผู้ปฏิบัติงานจึงต้องเลือกใช้เครื่องมือวัดที่มีพิกัดหมวดความปลอดภัย (Category Rating เช่น CAT III หรือ CAT IV) ให้เหมาะสมกับจุดที่ทำการวัด', 'เพราะพิกัดหมวดความปลอดภัยบ่งบอกถึงระดับพลังงานความผิดพร่องที่อาจเกิดขึ้น ณ จุดที่วัด ยิ่งใกล้แหล่งจ่ายไฟหลัก (เช่น สายป้อนจากหม้อแปลง) ยิ่งมีพลังงานความผิดพร่องสูง จำเป็นต้องใช้เครื่องมือที่มีพิกัดหมวดความปลอดภัยสูงกว่า (เช่น CAT IV) เพื่อป้องกันอันตรายจากการระเบิดของอาร์กไฟฟ้าหากเกิดความผิดพลาดขณะวัด', 'การใช้เครื่องมือวัดที่มีพิกัดต่ำกว่าที่จำเป็นในจุดที่มีพลังงานความผิดพร่องสูง เป็นสาเหตุสำคัญของอุบัติเหตุร้ายแรงจากอาร์กแฟลชที่เกิดขึ้นระหว่างการปฏิบัติงานตรวจวัดในภาคสนาม', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดผู้ปฏิบัติงานจึงต้องเลือกใช้เครื่องมือวัดที่มีพิกัดหมวดความปลอดภัย (Category Rating เช่น CAT III หรือ CAT IV) ให้เหมาะสมกับจุดที่ทำการวัด'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เครื่องวัดค่าตัวเก็บประจุ (Capacitance Meter หรือ LCR Meter) ใช้หลักการใดในการวัดค่าความจุ', 'โดยทั่วไปใช้หลักการจ่ายสัญญาณไฟฟ้ากระแสสลับความถี่ที่ทราบค่าเข้าไปยังตัวเก็บประจุที่ต้องการวัด แล้ววัดค่ากระแสหรือมุมเฟสที่เกิดขึ้น นำมาคำนวณย้อนกลับเป็นค่าความจุตามความสัมพันธ์ทางคณิตศาสตร์ของรีแอคแตนซ์ตัวเก็บประจุ', 'เครื่องมือ LCR Meter สามารถวัดได้ทั้งค่าความเหนี่ยวนำ (L) ความจุ (C) และความต้านทาน (R) ในเครื่องเดียว มีประโยชน์มากในการตรวจสอบชิ้นส่วนอิเล็กทรอนิกส์และวินิจฉัยความผิดปกติของตัวเก็บประจุที่เสื่อมสภาพในวงจรต่างๆ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เครื่องวัดค่าตัวเก็บประจุ (Capacitance Meter หรือ LCR Meter) ใช้หลักการใดในการวัดค่าความจุ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการตรวจสอบสภาพแบตเตอรี่แบบตะกั่วกรด (Lead-Acid Battery) ด้วยการวัดแรงดันวงจรเปิด (Open Circuit Voltage) เพียงอย่างเดียว จึงอาจไม่เพียงพอในการประเมินความสามารถในการใช้งานจริง', 'เพราะแรงดันวงจรเปิดบอกเพียงระดับการชาร์จโดยประมาณ แต่ไม่ได้สะท้อนถึงความสามารถในการจ่ายกระแสภายใต้ภาระจริง แบตเตอรี่ที่เสื่อมสภาพอาจยังคงแสดงแรงดันวงจรเปิดที่ดูปกติ แต่มีความต้านทานภายในสูงขึ้นมากจนไม่สามารถจ่ายกระแสได้เพียงพอเมื่อมีภาระจริงมากระทำ', 'การประเมินสภาพแบตเตอรี่ที่ครบถ้วนจึงต้องรวมการทดสอบภายใต้ภาระ (Load Test) หรือการวัดความต้านทานภายในควบคู่ไปกับการวัดแรงดันวงจรเปิด เพื่อให้ได้ภาพที่แท้จริงของความสามารถในการใช้งาน โดยเฉพาะสำหรับแบตเตอรี่ที่ใช้ในระบบสำรองไฟฟ้าที่สำคัญ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการตรวจสอบสภาพแบตเตอรี่แบบตะกั่วกรด (Lead-Acid Battery) ด้วยการวัดแรงดันวงจรเปิด (Open Circuit Voltage) เพียงอย่างเดียว จึงอาจไม่เพียงพอในการประเมินความสามารถในการใช้งานจริง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการวัดค่าฉนวนของสายเคเบิลแรงสูงที่ติดตั้งใต้ดินความยาวมาก จึงต้องพิจารณาผลของความจุสายที่สูงกว่าสายไฟทั่วไปในการเลือกวิธีทดสอบ', 'สายเคเบิลที่มีความยาวมากมีค่าความจุสูง เมื่อทำการทดสอบด้วยแรงดันไฟฟ้ากระแสตรง (เช่นในการวัดความต้านทานฉนวน) ตัวสายเคเบิลเองจะทำหน้าที่เก็บประจุคล้ายตัวเก็บประจุขนาดใหญ่ ทำให้ต้องใช้เวลานานกว่าปกติในการชาร์จประจุจนกระแสคงที่ ก่อนที่ค่าความต้านทานฉนวนที่วัดได้จะมีความหมายที่แท้จริง', 'ผู้ปฏิบัติงานต้องรอให้กระแสในการทดสอบคงที่ (Stabilize) ก่อนบันทึกค่า และควรมีการคายประจุ (Discharge) สายเคเบิลอย่างปลอดภัยหลังการทดสอบเสร็จสิ้น เนื่องจากพลังงานที่สะสมในสายเคเบิลความจุสูงอาจเป็นอันตรายต่อผู้ปฏิบัติงานหากไม่ได้คายประจุอย่างถูกวิธี', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการวัดค่าฉนวนของสายเคเบิลแรงสูงที่ติดตั้งใต้ดินความยาวมาก จึงต้องพิจารณาผลของความจุสายที่สูงกว่าสายไฟทั่วไปในการเลือกวิธีทดสอบ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรจึงควรทำความเข้าใจข้อจำกัดของเครื่องมือวัดแต่ละชนิดก่อนนำผลการวัดไปใช้ตัดสินใจทางวิศวกรรม แทนที่จะเชื่อตัวเลขที่แสดงบนหน้าจอโดยไม่ตั้งคำถาม', 'เพราะเครื่องมือวัดทุกชนิดมีข้อจำกัดเฉพาะตัว เช่น ช่วงความถี่ที่วัดได้ถูกต้อง ผลกระทบจาก Loading Effect ความไม่แน่นอนของการวัด หรือสภาวะแวดล้อมที่เหมาะสมในการใช้งาน หากใช้เครื่องมือผิดประเภทหรือผิดสภาวะ อาจได้ค่าที่ดูสมเหตุสมผลแต่คลาดเคลื่อนจากความเป็นจริงอย่างมีนัยสำคัญ', 'วิศวกรที่มีความเข้าใจลึกซึ้งในหลักการทำงานและข้อจำกัดของเครื่องมือวัด จะสามารถเลือกเครื่องมือที่เหมาะสมกับงาน ตีความผลการวัดได้อย่างถูกต้อง และรู้ว่าเมื่อใดควรตั้งข้อสงสัยต่อค่าที่วัดได้ ก่อนนำไปใช้ในการตัดสินใจที่สำคัญ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรจึงควรทำความเข้าใจข้อจำกัดของเครื่องมือวัดแต่ละชนิดก่อนนำผลการวัดไปใช้ตัดสินใจทางวิศวกรรม แทนที่จะเชื่อตัวเลขที่แสดงบนหน้าจอโดยไม่ตั้งคำถาม'
  );

commit;

-- ---------- ตรวจสอบผลลัพธ์ ----------
select c.name_th as category, count(q.id) as question_count
from categories c
left join questions q on q.category_id = c.id
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'instrumentation'
group by c.name_th;
